    const creditService = this.invoicesService.creditService;
    let balance = currentBalance;
    if (balance === undefined || balance === null) {
        const { balance: balanceStr } = await creditService.findCreditBalance({
            businessID: this.businessID,
            customerId: this.customerId,
        });
        balance = parseFloat(balanceStr);
    }
    const topUpAmount = parseFloat(this.topUpAmount);
    const thresholdRatio = parseFloat(this.topUpThreshold !== undefined ? this.topUpThreshold : '0.2');
    const threshold = thresholdRatio * topUpAmount;
    // Balance exactly at threshold is sufficient
    if (balance >= threshold) {
        return;
    }
    const unitCost = topUpAmount - balance;
    if (unitCost <= 0) {
        return;
    }
    const lineItems = new InvoiceLineItems();
    lineItems.addLineItem(new InvoiceLineItem(`${this.offeringName} - Top Up`, 1, unitCost));
    await this.invoicesService.create({
        businessID: this.businessID,
        customerId: this.customerId,
        customer,
        items: lineItems,
        currency: Offering.getCurrency({ customer, offering: this }),
        storePaymentAsCredit: true,
    });
}

