async processTopUpBilling(
    startDateOverride?: Date,
    endDateOverride?: Date,
    customer?: ReadCustomerResponseData,
): Promise<string> {
    const { startTime, endTime } = Billing.billingCycleToTimeRange(this.billingCycle);
    const startDate = startDateOverride ? startDateOverride : new Date(startTime);
    const endDate = endDateOverride ? endDateOverride : new Date(endTime);
    const lineItems = new InvoiceLineItems();
    await Offering.getLineItemsForUsage({
        startDate,
        endDate,
        customer,
        lineItems,
        negative: false,
        businessID: this.businessID,
        customerId: this.customerId,
        customerService: this.customerService,
        offeringInstance: this,
        dimensions: this.dimensions,
    });
    const creditService = this.invoicesService.creditService;
    const { balance: balanceStr } = await creditService.findCreditBalance({
        businessID: this.businessID,
        customerId: this.customerId,
    });
    let balance = parseFloat(balanceStr);
    const usageTotal = lineItems.getTotal();
    if (usageTotal > 0) {
        await creditService.create(
            {
                transactionAmount: (-usageTotal).toFixed(2),
                customerId: this.customerId,
                businessID: this.businessID,
                timestamp: new Date().toISOString(),
                metadata: {
                    reason: `Usage deduction for ${this.offeringName}`,
                    offeringId: this.offeringId,
                },
            },
            false,
            true,
        );
        balance = balance - usageTotal;
    }
    await this.topUp({ customer, currentBalance: balance });
    return;
}
